export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  fromProjectId: ProjectId,
  fromNumber: number,
  toProjectId: ProjectId,
  toNumber: number,
): Promise<Issue> {
  const db = getDb();
  return db.transaction((tx) => {
    tx.insert(projectNumberFloors)
      .values({ projectId: fromProjectId, orgId, maxNumber: fromNumber })
      .onConflictDoUpdate({
        target: projectNumberFloors.projectId,
        set: {
          maxNumber: sql`max(${projectNumberFloors.maxNumber}, ${fromNumber})`,
        },
      })
      .run();
    const row = tx
      .update(issues)
      .set({
        projectId: toProjectId,
        number: toNumber,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();
    if (!row) throw new Error(`Issue ${issueId} not found`);
    return toIssue(row);
  });
}
